@Configuration
public class CuadreCancelacionesJobConfig {

    @Bean
    Job cuadreCancelaciones(JobRepository repo,
                            Step validaPaso,          // 20000150-VAL-PASO
                            Step fechaProceso,        // 20000200-FECHA-PRO
                            Step unificaCopias,       // 20000700 / 20001000
                            Step cargaTablas,         // 20000800 / 20000850
                            Step totalesPorClave,     // 50004000 .. 50004560
                            Step cuadrePorClave) {    // 50005000 + 50006000
        return new JobBuilder("S500P110", repo)
                .start(validaPaso).next(fechaProceso).next(unificaCopias)
                .next(cargaTablas).next(totalesPorClave).next(cuadrePorClave)
                .listener(new TaskValueListener())   // SET MYSELF (TASKVALUE) TO W77-PAR-RESULT
                .build();
    }
}

/** El WFL que sigue a P110 lee el TASKVALUE: 0 sin diferencias, 99 con diferencias. */
class TaskValueListener implements JobExecutionListener {
    @Override
    public void afterJob(JobExecution je) {
        int taskValue = je.getExecutionContext().getInt("parResult", 0);
        je.setExitStatus(new ExitStatus(taskValue == 99 ? "CON_DIFERENCIAS" : "COMPLETED"));
    }
}

@Component
@RequiredArgsConstructor
class ControlPasoTasklet implements Tasklet {

    private static final int PASO_PREVIO = 105;           // p110.paso-previo
    private final ControlPasoRepository controlPaso;      // S500B00CTRLPASO

    @Override
    @Transactional                                        // BEGIN-TRANSACTION ... END-TRANSACTION SYNC
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        ControlPaso paso = controlPaso.findForUpdate()    // LOCK
                .orElseThrow(() -> new ProcesoAbortadoException("ERROR B00CTRLPASO NO EXISTE"));

        boolean p105Completo = paso.numPaso01() == PASO_PREVIO
                && paso.numPaso02() == PASO_PREVIO
                && paso.numPaso03() == PASO_PREVIO;       // R4-COPIAS-2011: tercera copia
        if (!p105Completo) {
            throw new ProcesoAbortadoException("ERROR BASE NO ES SALIDA DEL P105");
        }
        paso.reinicia();                                   // MOVE 0 a los tres campos y STORE
        return RepeatStatus.FINISHED;
    }
}

@Component
@RequiredArgsConstructor
class FechaProcesoTasklet implements Tasklet {

    private final ControlCaptacionRepository control;   // S500B02CONTROL

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        Control b02 = control.find()
                .orElseThrow(() -> new ProcesoAbortadoException("ERROR B02CONTROL NO EXISTE"));

        // Un solo objeto de contexto sustituye a las decenas de MOVE hacia WS-*-FEC y WS-*-CSI.
        var proceso = new ContextoProceso(
                Fechas.aaaammdd(b02.fechaLote()),   // B02-FECHA-LOTE, PIC 9(08)
                b02.numCsi());                      // B02-NUM-CSI: origen y destino a la vez

        ctx.getStepContext().getStepExecution().getJobExecution()
           .getExecutionContext().put("proceso", proceso);
        return RepeatStatus.FINISHED;
    }
}

/** Las etiquetas de archivo y los títulos de reporte se resuelven desde aquí. */
record ContextoProceso(LocalDate fecha, int csi) {
    String etiqueta(String plantilla) {
        return plantilla.replace("{csi}", "%02d".formatted(csi))
                        .replace("{fecha}", fecha.format(DateTimeFormatter.BASIC_ISO_DATE));
    }
}

/** REG-CANCEL1: 43 bytes, tipo de registro 9(02) y dos vistas REDEFINES. */
sealed interface CancelacionCopia permits CancelacionCopia.Header, CancelacionCopia.Detalle {
    record Header(int sistema, LocalDate fecProceso) implements CancelacionCopia {}
    record Detalle(int producto, int instrumento, int moneda, int sucursal,
                   String contrato,                 // 9(12): String para conservar ceros
                   BigDecimal importe)              // 9(12)V99 -> escala 2
            implements CancelacionCopia {}
}

@Component
@StepScope
class UnificaCopiaProcessor implements ItemProcessor<CancelacionCopia, Cancelacion> {

    @Value("#{jobExecutionContext['proceso']}") private ContextoProceso proceso;
    private boolean headerLeido;

    @Override
    public Cancelacion process(CancelacionCopia r) {
        if (!headerLeido) {                     // el primer registro siempre se trata como header
            headerLeido = true;
            var h = (CancelacionCopia.Header) r;
            if (!h.fecProceso().equals(proceso.fecha())) {
                throw new ProcesoAbortadoException("FEC.HEAD.C1 DIFERENTE A PRO");
            }
            return null;
        }
        var d = (CancelacionCopia.Detalle) r;   // todo lo demás es detalle, sin revisar el tipo
        return new Cancelacion(d.producto(), d.instrumento(), d.moneda(),
                               d.sucursal(), d.contrato(), d.importe());
    }
}
